import{_ as e,c as a,o as d,b0 as o}from"./chunks/framework.C5ev1SXp.js";const r="/scm-docs/assets/frame-encapsulation.jqaleLoh.svg",u=JSON.parse('{"title":"LV005-数据封装与以太网帧","description":null,"frontmatter":{"title":"LV005-数据封装与以太网帧","date":"2026-10-14T21:56:00.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/advanced-chapter/network-basics/126d628e1bb00a1f4c6d9e02","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-14T21:56:00.201Z","fulluuid":"a1f4c6d9e0204c5b8e3d7f6012ab45c7","useduuid":"a1f4c6d9e"}},"headers":[],"relativePath":"sdoc/advanced-chapter/network-basics/126d628e1bb00a1f4c6d9e02.md","filePath":"sdoc/30-进阶篇/05-网络基础/LV005-数据封装与以太网帧.md","lastUpdated":1792231946000}'),s={name:"sdoc/advanced-chapter/network-basics/126d628e1bb00a1f4c6d9e02.md"};function l(c,t,i,n,h,p){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="lv005-数据封装与以太网帧" tabindex="-1">LV005-数据封装与以太网帧 <a class="header-anchor" href="#lv005-数据封装与以太网帧" aria-label="Permalink to &quot;LV005-数据封装与以太网帧&quot;">​</a></h1><h2 id="一、-为什么要逐层封装" tabindex="-1">一、 为什么要逐层封装 <a class="header-anchor" href="#一、-为什么要逐层封装" aria-label="Permalink to &quot;一、 为什么要逐层封装&quot;">​</a></h2><h3 id="_1-封装解决了什么问题" tabindex="-1">1. 封装解决了什么问题 <a class="header-anchor" href="#_1-封装解决了什么问题" aria-label="Permalink to &quot;1. 封装解决了什么问题&quot;">​</a></h3><p>上一篇说了&quot;分层&quot;，但分层只是说了&quot;谁管什么&quot;，真正让各层能拼起来工作的机制是<strong>封装</strong>。</p><p>封装要解决的是一个很朴素的矛盾：<strong>每一层都需要在数据前面写一点自己的信息，但又不能要求上层知道下层要写什么。</strong></p><p>于是规矩定成了这样：</p><ul><li>每一层只关心&quot;我要在别人的数据前面加什么&quot;，加完就整体交给下一层；</li><li>下一层把这个&quot;上层的东西&quot;整体当成自己的数据，继续在前面加自己的头。</li></ul><p>这样一来，上层不用知道以太网帧头有几个字节，下层也不用知道 IP 头里放了什么，<strong>层与层之间靠&quot;整体当作数据&quot;解耦</strong>。</p><h3 id="_2-封装与解封装的对称性" tabindex="-1">2. 封装与解封装的对称性 <a class="header-anchor" href="#_2-封装与解封装的对称性" aria-label="Permalink to &quot;2. 封装与解封装的对称性&quot;">​</a></h3><p>发送方从下往上加头，接收方从上往下脱头，两边的顺序正好相反：</p><table tabindex="0"><thead><tr><th>方向</th><th>顺序</th></tr></thead><tbody><tr><td>发送（封装）</td><td>应用数据 → 加 TCP/UDP 头 → 加 IP 头 → 加以太网头 → 发出</td></tr><tr><td>接收（解封装）</td><td>收到帧 → 脱以太网头 → 脱 IP 头 → 脱 TCP/UDP 头 → 交给应用</td></tr></tbody></table><p>每一层脱头后都会做一次判断：<strong>这个包是不是给我的？</strong> 判断依据就在该层自己的头里：</p><ul><li>链路层看目的 MAC 是不是自己（或者是广播 / 组播）；</li><li>网络层看目的 IP 是不是自己、是否允许转发；</li><li>传输层看目的端口有没有程序在监听。</li></ul><p>只要有一层判断为&quot;不是给我的&quot;，包就在这里被丢掉或者被转发出去，不会再往上走。</p><h2 id="二、-以太网帧的字段构成" tabindex="-1">二、 以太网帧的字段构成 <a class="header-anchor" href="#二、-以太网帧的字段构成" aria-label="Permalink to &quot;二、 以太网帧的字段构成&quot;">​</a></h2><h3 id="_1-帧头-14-字节" tabindex="-1">1. 帧头 14 字节 <a class="header-anchor" href="#_1-帧头-14-字节" aria-label="Permalink to &quot;1. 帧头 14 字节&quot;">​</a></h3><p>以太网（Ethernet II，也就是现在通用的 DIX 格式）帧的组成是固定的：</p><table tabindex="0"><thead><tr><th>字段</th><th>长度</th><th>说明</th></tr></thead><tbody><tr><td>目的 MAC</td><td>6 字节</td><td>这一跳要把帧交给谁；广播为 <code>FF:FF:FF:FF:FF:FF</code></td></tr><tr><td>源 MAC</td><td>6 字节</td><td>这一跳是谁发的</td></tr><tr><td>类型</td><td>2 字节</td><td>里面装的是什么：<code>0x0800</code> = IPv4，<code>0x0806</code> = ARP，<code>0x86DD</code> = IPv6</td></tr><tr><td>数据</td><td>46 ~ 1500 字节</td><td>上层的内容，最长 1500 字节（MTU）</td></tr><tr><td>帧校验序列 FCS</td><td>4 字节</td><td>32 位 CRC，由网卡硬件生成与校验</td></tr></tbody></table><p>前面的&quot;目的 MAC + 源 MAC + 类型&quot;共 14 字节，就是常说的<strong>以太网头</strong>。</p><h3 id="_2-帧尾的-fcs-与填充" tabindex="-1">2. 帧尾的 FCS 与填充 <a class="header-anchor" href="#_2-帧尾的-fcs-与填充" aria-label="Permalink to &quot;2. 帧尾的 FCS 与填充&quot;">​</a></h3><p>两件事容易被忽略：</p><p>（1）<strong>FCS 不参与上层</strong>。它由发送网卡的硬件算出来、由接收网卡的硬件校验，协议栈里根本看不到这 4 个字节。所以抓包工具算出来的&quot;帧长&quot;通常不含 FCS。</p><p>（2）<strong>数据不足 46 字节要填充</strong>。以太网规定帧最短 64 字节（不含前导码），减掉 14 字节头与 4 字节 FCS，数据部分至少要有 46 字节。一个 ARP 报文只有 28 字节，剩余 18 字节就是填充出来的。</p><p>这一点在写驱动时有实际影响：收到只有 42 字节的 ARP 帧时，长度字段给出的是真实长度（42），后面的填充字节并不需要关心。</p><h3 id="_3-类型字段是分流的依据" tabindex="-1">3. 类型字段是分流的依据 <a class="header-anchor" href="#_3-类型字段是分流的依据" aria-label="Permalink to &quot;3. 类型字段是分流的依据&quot;">​</a></h3><p>交换机之后的设备拿到一个帧，要做的第一件事就是看类型字段，决定交给谁处理。这正是 lwIP 里 <code>ethernet_input()</code> 干的事：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Components/lwip-2.1.3/src/core/ipv4/ethernet.c</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">switch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (type) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">case</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> PP_HTONS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ETHTYPE_IP):</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* 0x0800 → 交给 IP 层 */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">case</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> PP_HTONS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ETHTYPE_ARP):</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  /* 0x0806 → 交给 ARP */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>在 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb01bacb81dfb86.html">LV030-ARP与MAC地址</a> 里会看到，这个 switch 就是&quot;ARP 与 IP 共存于同一块网卡&quot;的实现方式。</p><h2 id="三、-一次-ping-报文的逐层拆解" tabindex="-1">三、 一次 ping 报文的逐层拆解 <a class="header-anchor" href="#三、-一次-ping-报文的逐层拆解" aria-label="Permalink to &quot;三、 一次 ping 报文的逐层拆解&quot;">​</a></h2><h3 id="_1-从应用到链路" tabindex="-1">1. 从应用到链路 <a class="header-anchor" href="#_1-从应用到链路" aria-label="Permalink to &quot;1. 从应用到链路&quot;">​</a></h3><p>板子 Ping 应答时的完整报文体（不含填充与 FCS）：</p><table tabindex="0"><thead><tr><th>层级</th><th>头部长度</th><th>本包里的关键取值</th></tr></thead><tbody><tr><td>以太网头</td><td>14 字节</td><td>目的 MAC = PC 的 MAC，源 MAC = 板子的 MAC，类型 = <code>0x0800</code></td></tr><tr><td>IP 头</td><td>20 字节</td><td>源 IP = <code>192.168.16.30</code>，目的 IP = <code>192.168.16.100</code>，协议号 = 1（ICMP）</td></tr><tr><td>ICMP 头</td><td>8 字节</td><td>类型 = 0（应答）、代码 = 0、校验和、标识、序号</td></tr><tr><td>ICMP 数据</td><td>可变</td><td><code>ping</code> 默认 32 或 56 字节，内容由 ping 程序自己填</td></tr></tbody></table><img src="`+r+`" alt="以太网帧、IP 头与 ICMP 报文的字段与长度"><h3 id="_2-各层校验覆盖的范围" tabindex="-1">2. 各层校验覆盖的范围 <a class="header-anchor" href="#_2-各层校验覆盖的范围" aria-label="Permalink to &quot;2. 各层校验覆盖的范围&quot;">​</a></h3><p>校验是分层的另一个体现——每层只校验自己该负责的部分：</p><table tabindex="0"><thead><tr><th>校验</th><th>由谁负责</th><th>覆盖范围</th></tr></thead><tbody><tr><td>FCS</td><td>网卡硬件</td><td>整个帧（不含前导码）</td></tr><tr><td>IP 头校验和</td><td>IP 层（软件或硬件）</td><td>只覆盖 IP 头，不含数据</td></tr><tr><td>ICMP 校验和</td><td>ICMP 层</td><td>ICMP 头 + ICMP 数据</td></tr><tr><td>TCP/UDP 校验和</td><td>传输层</td><td>头 + 数据 + 伪首部</td></tr></tbody></table><p>本工程在 <code>lwipopts.h</code> 里把六个 <code>CHECKSUM_*</code> 全部打开，收发都校验，代价是每次收发多花一点 CPU——对 72 MHz 的 M3 来说这点开销换来的排错价值是值得的。</p><h3 id="_3-协议号连接上下层" tabindex="-1">3. 协议号连接上下层 <a class="header-anchor" href="#_3-协议号连接上下层" aria-label="Permalink to &quot;3. 协议号连接上下层&quot;">​</a></h3><p>IP 头里的<strong>协议号</strong>字段决定了载荷交给谁，作用与以太网的类型字段完全一样：</p><table tabindex="0"><thead><tr><th>协议号</th><th>交给谁</th></tr></thead><tbody><tr><td>1</td><td>ICMP</td></tr><tr><td>6</td><td>TCP</td></tr><tr><td>17</td><td>UDP</td></tr></tbody></table><p>所以一条完整的分流链是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>以太网类型 0x0800 ──▶ IP 层 ──协议号 1──▶ ICMP</span></span>
<span class="line"><span>以太网类型 0x0806 ──▶ ARP 层</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="四、-mtu、最小帧长与分片" tabindex="-1">四、 MTU、最小帧长与分片 <a class="header-anchor" href="#四、-mtu、最小帧长与分片" aria-label="Permalink to &quot;四、 MTU、最小帧长与分片&quot;">​</a></h2><h3 id="_1-mtu-与-mss" tabindex="-1">1. MTU 与 MSS <a class="header-anchor" href="#_1-mtu-与-mss" aria-label="Permalink to &quot;1. MTU 与 MSS&quot;">​</a></h3><p>**MTU（最大传输单元）**指一层能承载的上层数据最大值。以太网的 MTU 是 1500 字节，所以一个 IP 包最长 1500 字节（含 IP 头）。</p><p>在 TCP 里还有一个相关概念 <strong>MSS</strong>（最大报文段长度）：指一个 TCP 段最多能装多少数据。以太网下理论上限是 MTU - IP 头 - TCP 头 = 1500 - 20 - 20 = <strong>1460 字节</strong>，但实际值由<strong>连接双方在握手时各自宣布</strong>、发送方按&quot;对方宣布的 MSS&quot;来切分。</p><p>对应到本工程，要区分两件事：</p><p>（1）上位机脚本 <code>tools/send_iap_tcp.py</code> 里 <code>CHUNK = 1460</code>，那只是脚本<strong>每次调用 <code>sendall()</code> 写入的字节数</strong>，不等于线上分段大小。</p><p>（2）真正决定线上分段的是板子在握手里宣布的 MSS——本工程 <code>lwipopts.h</code> 没定义 <code>TCP_MSS</code>，走 lwIP 默认值 <strong>536</strong>，所以 PC 的协议栈实际会按 ≤ 536 字节切分发送。两者的完整解释见 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a51d3a6f2be804.html">LV015-lwIP配置与初始化</a> 第二节与 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb02d6a3f5e9c41.html">LV035-传输层端口UDP与TCP</a> 第三节。</p><h3 id="_2-超过-mtu-会怎样-分片" tabindex="-1">2. 超过 MTU 会怎样：分片 <a class="header-anchor" href="#_2-超过-mtu-会怎样-分片" aria-label="Permalink to &quot;2. 超过 MTU 会怎样：分片&quot;">​</a></h3><p>如果上层给下来的数据超过 MTU，IP 层有两种处理方式：</p><p>（1）<strong>分片（Fragmentation）</strong>：把一个 IP 包拆成多个小包，每个都有自己的 IP 头，接收端再重组。开销是每个分片都要单独封装与校验，且任何一片丢失都要整包重传。</p><p>（2）<strong>由上层保证不超过 MTU</strong>：比如 TCP 自己按 MSS 切分。</p><p>本工程的做法是第二条，并且<strong>直接把分片功能关掉</strong>：</p><table tabindex="0"><thead><tr><th>宏</th><th>取值</th><th>含义</th></tr></thead><tbody><tr><td><code>IP_REASSEMBLY</code></td><td>0</td><td>不做分片重组</td></tr><tr><td><code>IP_FRAG</code></td><td>0</td><td>不主动分片</td></tr></tbody></table><p>这样做的理由很直接：重组需要额外的缓冲与定时器，而本工程的 <code>MEM_SIZE</code> 只有 8 KB。关掉之后，一旦收到分片包会被直接丢弃——如果哪天真遇到&quot;大包不通小包通&quot;，第一个要怀疑的就是这里。</p><h3 id="_3-对驱动的约束" tabindex="-1">3. 对驱动的约束 <a class="header-anchor" href="#_3-对驱动的约束" aria-label="Permalink to &quot;3. 对驱动的约束&quot;">​</a></h3><p>MTU 决定了驱动要准备多大的接收缓冲。<code>ethernetif.c</code> 把接口的 MTU 设成 1500 后，DM9000 驱动里给单个包预留的上限是 <code>DM9000_PKT_MAX = 1536</code> 字节（1500 + 14 以太网头 + 余量），见 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5187d4be5a1c9.html">LV005-DM9000驱动实现</a> 第五节。</p><h2 id="五、-lwip-里的报文结构与收发缓冲" tabindex="-1">五、 lwIP 里的报文结构与收发缓冲 <a class="header-anchor" href="#五、-lwip-里的报文结构与收发缓冲" aria-label="Permalink to &quot;五、 lwIP 里的报文结构与收发缓冲&quot;">​</a></h2><h3 id="_1-头部结构体与协议一一对应" tabindex="-1">1. 头部结构体与协议一一对应 <a class="header-anchor" href="#_1-头部结构体与协议一一对应" aria-label="Permalink to &quot;1. 头部结构体与协议一一对应&quot;">​</a></h3><p>lwIP 把每个头部都定义成结构体，字段顺序与协议规定完全一致：</p><table tabindex="0"><thead><tr><th>结构体</th><th>对应头部</th><th>声明位置</th></tr></thead><tbody><tr><td><code>struct eth_hdr</code></td><td>14 字节以太网头</td><td><code>src/include/lwip/prot/ethernet.h</code></td></tr><tr><td><code>struct ip_hdr</code></td><td>IP 头</td><td><code>src/include/lwip/prot/ip4.h</code></td></tr><tr><td><code>struct icmp_echo_hdr</code></td><td>ICMP 回显头</td><td><code>src/include/lwip/prot/icmp.h</code></td></tr><tr><td><code>struct tcp_hdr</code></td><td>TCP 头</td><td><code>src/include/lwip/prot/tcp.h</code></td></tr></tbody></table><p><strong>这组结构体必须按字节紧密排布</strong>，否则读到的字段会整体错位。这也是 <code>port/arch/cc.h</code> 里那组 <code>PACK_STRUCT_*</code> 宏不能省的原因，详见 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a51b6ce0b937cd.html">LV010-lwIP协议栈移植</a> 第二节。</p><h3 id="_2-pbuf-贯穿各层的缓冲结构" tabindex="-1">2. pbuf：贯穿各层的缓冲结构 <a class="header-anchor" href="#_2-pbuf-贯穿各层的缓冲结构" aria-label="Permalink to &quot;2. pbuf：贯穿各层的缓冲结构&quot;">​</a></h3><p>lwIP 用一个叫 <code>pbuf</code> 的结构在不同层之间传递数据。它的关键特点是<strong>支持链式</strong>：一个包可以由多个 <code>pbuf</code> 串起来，每个 <code>pbuf</code> 指向内存中一段连续区域。</p><p>这样做的好处是收包时不一定要把整包数据搬到一起：</p><ul><li>DM9000 驱动从 RX FIFO 读出数据后，从 <code>PBUF_POOL</code> 里申请一个 <code>pbuf</code> 装进去；</li><li>上层只在前面&quot;预留&quot;出头部空间（<code>pbuf_alloc</code> 的 <code>offset</code>），要加头时直接在预留区写，不用搬动数据。</li></ul><p>本工程把 <code>PBUF_POOL_SIZE</code> 定为 8、<code>MEMP_NUM_PBUF</code> 定为 8，也就是最多同时容纳 8 个池化 <code>pbuf</code>。池子用光时 <code>pbuf_alloc</code> 会返回 NULL，驱动里的表现就是&quot;包被丢弃并打印 <code>pbuf alloc failed</code>&quot;——这是排查丢包时最值得先看的一条计数。</p><h2 id="六、-小结与参考资料" tabindex="-1">六、 小结与参考资料 <a class="header-anchor" href="#六、-小结与参考资料" aria-label="Permalink to &quot;六、 小结与参考资料&quot;">​</a></h2><h3 id="_1-本篇小结" tabindex="-1">1. 本篇小结 <a class="header-anchor" href="#_1-本篇小结" aria-label="Permalink to &quot;1. 本篇小结&quot;">​</a></h3><ul><li>封装让每层只需在数据前面加自己的头，层与层之间靠&quot;整体当数据&quot;解耦；收包时逐层脱头，每层都判断&quot;是不是给我的&quot;。</li><li>以太网帧 = 14 字节头（目的 MAC、源 MAC、类型）+ 46~1500 字节数据 + 4 字节 FCS；不足 46 字节要填充。</li><li>类型字段（<code>0x0800</code> / <code>0x0806</code>）与 IP 协议号（1 / 6 / 17）是两级分流依据。</li><li>以太网 MTU 是 1500 字节，TCP 的 MSS 是 1460 字节，上位机按 MSS 切帧。</li><li>本工程关掉了 <code>IP_REASSEMBLY</code> 与 <code>IP_FRAG</code>，遇到分片包直接丢。</li><li>lwIP 用 <code>ip_hdr</code>、<code>eth_hdr</code> 等结构体解析头部，靠 <code>PACK_STRUCT_*</code> 宏保证紧密排布；数据用可链式的 <code>pbuf</code> 传递。</li></ul><h3 id="_2-参考资料" tabindex="-1">2. 参考资料 <a class="header-anchor" href="#_2-参考资料" aria-label="Permalink to &quot;2. 参考资料&quot;">​</a></h3><ul><li>以太网的收发与分流：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Components/lwip-2.1.3/src/core/ipv4/ethernet.c" target="_blank" rel="noreferrer"><code>ethernet.c</code></a></li><li>协议栈裁剪（MTU 与分片相关宏）：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Components/lwip-2.1.3/port/lwipopts.h" target="_blank" rel="noreferrer"><code>lwipopts.h</code></a></li><li>上位机切帧：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/tools/send_iap_tcp.py" target="_blank" rel="noreferrer"><code>tools/send_iap_tcp.py</code></a></li><li>手册：<a href="https://gitee.com/docs-site/scm-reference-guide/raw/main/30-STM32%E8%B5%84%E6%96%99/10-lwIP/STM32F1%20LWIP%E5%BC%80%E5%8F%91%E6%89%8B%E5%86%8C%28DM9000%E7%89%88%29_V1.1.pdf" target="_blank" rel="noreferrer"><code>STM32F1 LWIP开发手册(DM9000版)_V1.1.pdf</code></a> 第 1.1 节</li></ul><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>`,75)])])}const P=e(s,[["render",l]]);export{u as __pageData,P as default};
